import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n_values = scanner.nextInt();
        int[] values = new int[n_values];
        for (int i = 0; i < n_values; i++) {
            values[i] = scanner.nextInt();
        }
        int interval_value = scanner.nextInt();
        Arrays.sort(values);
        int max_subset = 0;
        for (int start_idx = 0; start_idx < n_values; start_idx++) {
            int count = 0;
            for (int k = start_idx; k < n_values; k++) {
                if (values[k] <= values[start_idx] + interval_value) {
                    count++;
                }
            }
            max_subset = Math.max(max_subset, count);
        }
        System.out.println(max_subset);
        scanner.close();
    }
}
